/* BERTH.A RC225 — Kids · Corujinha Lunar · 5 acessórios × 3 cores
   Incremental sobre RC224. Preserva Gato Neblina, Coelho de Nuvem, Raposa e trilha Kids.
   Também normaliza levemente a escala visual da Raposa para aproximar dos packs anteriores.
*/
(function(){
'use strict';
const BUILD='RC225';
const PALS=['nevoa','coral','misto'];
const PREFIX='bertha.kids.accessory.variant.';
const IDS={
  'mist_mist_v1_owl_head_0':'head',
  'mist_mist_v1_owl_neck_1':'neck',
  'mist_mist_v1_owl_eyes_2':'eyes',
  'mist_mist_v1_owl_back_3':'back',
  'mist_mist_v1_owl_special_4':'special'
};
const NAMES={
  'mist_mist_v1_owl_head_0':'Chapéu Pena Lunar',
  'mist_mist_v1_owl_neck_1':'Gravata Lua-Sábia',
  'mist_mist_v1_owl_eyes_2':'Óculos de Leitura Lunar',
  'mist_mist_v1_owl_back_3':'Bolsa-Livro Celeste',
  'mist_mist_v1_owl_special_4':'Medalhão Pena Oráculo'
};
const ASSETS={
    'head-nevoa':'data:image/png;base64,',
    'head-coral':'data:image/png;base64,',
    'head-misto':'data:image/png;base64,',
    'neck-nevoa':'data:image/png;base64,',
    'neck-coral':'data:image/png;base64,',
    'neck-misto':'data:image/png;base64,',
    'eyes-nevoa':'data:image/png;base64,',
    'eyes-coral':'data:image/png;base64,',
    'eyes-misto':'data:image/png;base64,',
    'back-nevoa':'data:image/png;base64,',
    'back-coral':'data:image/png;base64,',
    'back-misto':'data:image/png;base64,',
    'special-nevoa':'data:image/png;base64,',
    'special-coral':'data:image/png;base64,',
    'special-misto':'data:image/png;base64,'
};
const store=()=>window.berthaHmlStorage||window.localStorage;
function selectedKid(){const s=document.querySelector('#r152KidSel');if(s&&s.value)return String(s.value);if(window.__rc209Member!=null)return String(window.__rc209Member);return 'default';}
function variantFor(aid){const n=Number(store().getItem(PREFIX+selectedKid()+'.'+aid));return Number.isFinite(n)?Math.max(0,Math.min(2,n)):0;}
function srcFor(aid){const kind=IDS[aid];return kind?ASSETS[kind+'-'+PALS[variantFor(aid)]]:'';}
function stamp(){ /* RC227: build badge owned only by final patch */ }
function patch(root=document){
  root.querySelectorAll('.rc209-acc-proxy[data-acc]').forEach(proxy=>{
    const aid=proxy.getAttribute('data-acc');if(!IDS[aid])return;
    const src=srcFor(aid);proxy.classList.add('rc225-owl-asset');proxy.dataset.rc225='1';
    let im=proxy.querySelector('img');if(!im){proxy.replaceChildren();im=document.createElement('img');im.alt='';im.loading='eager';im.decoding='async';proxy.appendChild(im);}
    if(im.getAttribute('src')!==src)im.setAttribute('src',src);
    const card=proxy.closest('.r197-acc');if(card){const s=card.querySelector('strong');if(s&&NAMES[aid])s.textContent=NAMES[aid];}
  });
  stamp();
}
const style=document.createElement('style');style.id='rc225-owl-assets-style';style.textContent=`
.r197-acc-art .rc225-owl-asset{display:flex!important;align-items:center!important;justify-content:center!important;width:100%!important;height:100%!important;min-height:156px!important;overflow:visible!important;background:transparent!important}
.r197-acc-art .rc225-owl-asset img{display:block!important;width:98%!important;height:154px!important;object-fit:contain!important;object-position:center!important;filter:none!important;transform:none!important}
.r197-acc:has(.rc225-owl-asset) .r197-acc-art{min-height:162px!important;overflow:visible!important}
/* leve normalização visual da Raposa: sem trocar assets */
.r197-acc-art .rc224-fox-asset img{width:98%!important;height:150px!important}
.r197-acc-art .rc224-fox-asset{min-height:154px!important}
`;document.head.appendChild(style);
Object.values(ASSETS).forEach(src=>{const i=new Image();i.decoding='async';i.src=src;});
let raf=0;const schedule=()=>{if(raf)return;raf=requestAnimationFrame(()=>{raf=0;patch(document);});};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',schedule,{once:true});else schedule();
window.addEventListener('pageshow',schedule);window.addEventListener('hashchange',()=>setTimeout(schedule,30));document.addEventListener('click',e=>{if(e.target.closest('[data-rc209variant],[data-r152pet],#rc208PetSel,#rc208CollectionSel'))setTimeout(schedule,30);},true);/* RC227: global MutationObserver removed to prevent cross-patch render loop */
})();
